(()=>{const KEY='lkuni.language';const dictionaries={ru:{language:'RU',logout:'Выйти',showPassword:'Показать пароль',hidePassword:'Скрыть пароль'},en:{language:'EN',logout:'Sign out',showPassword:'Show password',hidePassword:'Hide password'}};function current(){return localStorage.getItem(KEY)||'ru'}function accessToken(){return localStorage.getItem('lkuni.accessToken')||sessionStorage.getItem('lkuni.accessToken')||''}async function persistAuthenticatedLanguage(language){const token=accessToken();if(!token)return;try{await fetch('/api/v1/profile/settings',{method:'PATCH',headers:{'content-type':'application/json','authorization':'Bearer '+token},body:JSON.stringify({language})})}catch{}}function set(lang,source='programmatic'){const next=lang==='en'?'en':'ru';localStorage.setItem(KEY,next);document.documentElement.lang=next;document.dispatchEvent(new CustomEvent('lkuni:language',{detail:{language:next,source}}));if(source==='user')persistAuthenticatedLanguage(next);return next}function toggle(){return set(current()==='ru'?'en':'ru','user')}function text(key,lang=current()){return dictionaries[lang]?.[key]||dictionaries.ru[key]||key}function renderButton(button){if(!button)return;button.textContent=current()==='ru'?'RU · EN':'EN · RU';button.setAttribute('aria-label',current()==='ru'?'Switch interface to English':'Переключить интерфейс на русский')}function bindButton(button){if(!button)return;if(button.dataset.lkuniI18nBound!=='1'){button.dataset.lkuniI18nBound='1';button.addEventListener('click',()=>toggle());document.addEventListener('lkuni:language',()=>renderButton(button))}renderButton(button)}function ensurePasswordStyles(){if(document.getElementById('lkuni-password-toggle-style'))return;const style=document.createElement('style');style.id='lkuni-password-toggle-style';style.textContent='.lkuni-password-wrap{position:relative;display:block}.lkuni-password-wrap>input{width:100%;padding-right:48px!important}.lkuni-password-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);width:36px;height:36px;border:0;background:transparent;border-radius:9px;display:grid;place-items:center;cursor:pointer;color:#667085;padding:0}.lkuni-password-toggle:hover{background:#f4f7fb;color:#172033}.lkuni-password-toggle:focus-visible{outline:2px solid #2458d3;outline-offset:2px}.lkuni-password-toggle svg{width:20px;height:20px;pointer-events:none}';document.head.appendChild(style)}function passwordIcon(visible){return visible?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 10.6a2 2 0 002.8 2.8"/><path d="M9.9 4.2A10.6 10.6 0 0112 4c5 0 9 4 10 8a11.4 11.4 0 01-2.1 3.9"/><path d="M6.2 6.2A11.7 11.7 0 002 12c1 4 5 8 10 8a10 10 0 005.1-1.4"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>'}function bindPasswordToggle(input){if(!input||input.dataset.lkuniPasswordBound==='1')return;if(input.closest('.password-wrap')||input.parentElement?.querySelector('.password-toggle'))return;ensurePasswordStyles();input.dataset.lkuniPasswordBound='1';const wrap=document.createElement('div');wrap.className='lkuni-password-wrap';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);const button=document.createElement('button');button.type='button';button.className='lkuni-password-toggle';wrap.appendChild(button);function render(){const visible=input.type==='text';button.innerHTML=passwordIcon(visible);const label=text(visible?'hidePassword':'showPassword');button.setAttribute('aria-label',label);button.setAttribute('title',label);button.setAttribute('aria-pressed',visible?'true':'false')}button.addEventListener('click',()=>{input.type=input.type==='password'?'text':'password';render();input.focus({preventScroll:true})});document.addEventListener('lkuni:language',render);render()}function bindAllPasswordToggles(root=document){root.querySelectorAll('input[type="password"]').forEach(bindPasswordToggle)}window.LkUniI18n={current,set,toggle,text,bindButton,bindPasswordToggle,bindAllPasswordToggles};document.documentElement.lang=current();bindAllPasswordToggles()})();